import pikepdf

def set_field_value(field, value):
    """Set a field value in a nested field structure"""
    field['/V'] = value
    if '/AP' in field:
        del field['/AP']  # Clear appearance stream to force re-render

def find_and_set_field(fields, field_path, value):
    """Find a field by path and set its value"""
    current = fields[0]  # Start with root

    # Navigate through the path
    path_parts = field_path.split('.')

    for part in path_parts[:-1]:
        if '/Kids' in current:
            for kid in current['/Kids']:
                if kid['/T'] == part:
                    current = kid
                    break

    # Find and set the target field
    if '/Kids' in current:
        for kid in current['/Kids']:
            if kid['/T'] == path_parts[-1]:
                set_field_value(kid, value)
                return True

    # If not found with navigation, search recursively
    def search_and_set(field, target_name):
        if '/T' in field:
            t_value = str(field['/T']).strip("()")
            if t_value == target_name:
                set_field_value(field, value)
                return True

        if '/Kids' in field:
            for kid in field['/Kids']:
                if search_and_set(kid, target_name):
                    return True
        return False

    return search_and_set(current, path_parts[-1])

def fill_form(pdf_path, output_path, data_dict):
    """Fill PDF form with provided data"""
    with pikepdf.open(pdf_path) as pdf:
        fields = pdf.Root.AcroForm.Fields

        # Recursively search for and fill fields
        def search_and_fill(field, field_name, value):
            if '/T' in field:
                t_value = str(field['/T']).strip("()")
                if t_value == field_name:
                    set_field_value(field, value)
                    return True

            if '/Kids' in field:
                for kid in field['/Kids']:
                    if search_and_fill(kid, field_name, value):
                        return True
            return False

        # Fill each field
        for field_name, value in data_dict.items():
            for field in fields:
                if search_and_fill(field, field_name, value):
                    break

        pdf.save(output_path)

# Prepare data
form_data = {
    # Plaintiff information (Page 2)
