import pikepdf

def print_filled_fields(pdf_path):
    """Print all fields that have values"""
    with pikepdf.open(pdf_path) as pdf:
        fields = pdf.Root.AcroForm.Fields

        filled_fields = []

        def search_fields(field):
            if '/T' in field and '/V' in field:
                t_value = str(field['/T']).strip("()")
                v_value = str(field['/V']).strip("()")
                if v_value and v_value != '/Off':
                    # Remove index from field name
                    clean_name = t_value.replace('[0]', '')
                    filled_fields.append((clean_name, v_value))

            if '/Kids' in field:
                for kid in field['/Kids']:
                    search_fields(kid)

        for field in fields:
            search_fields(field)

        print("Filled fields in the output PDF:")
        print("-" * 70)
        for name, value in sorted(set(filled_fields)):
            print(f"{name:30} : {value}")

print_filled_fields('/root/sc100-filled.pdf')
